-- 5. Sightseeing Places (Exact 22 Places from Database)
INSERT OR REPLACE INTO places (id, title, slug, category, distance_bhuj, best_time, short_desc, description, image, sort_order, is_active) VALUES
  (1, 'WHITE RANN OF KUTCH', 'white-rann', 'DESERT', '80 km', 'October to February — cool winter weather with the salt desert at its brightest white, perfect for sightseeing and photo', 'The White Desert of Kutch is a breathtaking salt desert famous for its endless white landscape, stunning sunsets, cultural experiences, and the vibrant atmosphere of the Rann Utsav.', 'The White Rann of Kutch is one of the largest salt deserts in the world and a breathtaking natural wonder located in the Kutch district of Gujarat. Stretching endlessly to the horizon, this dazzling white landscape is formed by the salt marshes of the Great Rann and turns into a shimmering sea of white during the dry winter months. Under the moonlight, the entire desert glows like a silver blanket, creating a magical and unforgettable sight. A visit to the White Rann is incomplete without experiencing its serene sunsets and star-filled skies. Since the desert is located in a remote area, travellers usually book a convenient taxi, cab, or tempo traveller service from Bhuj to reach here comfortably. Whether you are planning a family trip or a group tour, hiring a reliable car rental or bus service for the White Rann of Kutch ensures a smooth and enjoyable journey to this iconic destination.', 'white-rann.jpg', 1, 1),
  (2, 'UNESCO WORLD HERITAGE SITE  DHOLAVIRA', 'dholavira', 'Archaeological', '250 km', 'October to March — pleasant winter weather ideal for exploring the ancient ruins and enjoying the scenic desert drive.', 'Dholavira is a remarkable UNESCO World Heritage Site and one of the best-preserved ancient Harappan cities, known for its advanced urban planning, water management, and fascinating archaeological remains.', 'Dholavira is a UNESCO World Heritage Site and one of the most remarkable archaeological sites of the ancient Indus Valley Civilisation, located on Khadir Bet island in the Kutch district of Gujarat. Dating back over 4,500 years, this ancient city showcases an advanced urban planning system, sophisticated water conservation structures, reservoirs, and well-laid streets that reflect the brilliance of the Harappan people. Excavations here have revealed fascinating artefacts, seals, and the world''s oldest known signboard, making Dholavira a treasure trove for history lovers and curious travellers alike. Surrounded by the vast white desert landscape, the journey to this heritage site is an experience in itself. As Dholavira is located in a remote region, travellers prefer booking a comfortable taxi, cab, or tempo traveller service from Bhuj for a smooth trip. Whether visiting with family or in a group, hiring a reliable car rental or bus service for Dholavira makes exploring this ancient wonder convenient and memorable.', 'dholavira.jpg', 2, 1),
  (7, 'MATA NO MADH', 'mata-no-madh', 'TEMPLE', '95 km', 'October to March, especially during Navratri, when the temple hosts grand celebrations and the winter weather is pleasan', 'Mata No Madh is a famous pilgrimage site in Kutch, Gujarat, dedicated to Maa Ashapura, the revered deity of the Kutch region. Surrounded by scenic landscapes, the temple attracts thousands of devotees seeking blessings and spiritual peace.', 'Mata No Madh is one of the most important and revered pilgrimage sites in the Kutch district of Gujarat, home to the famous Ashapura Mata Temple. Dedicated to Ashapura Mata, the presiding deity and kuldevi of the Kutch region, this ancient temple holds deep religious significance for millions of devotees. Located around 95 kilometres from Bhuj, the temple attracts a huge number of pilgrims, especially during Navratri, when grand celebrations and fairs are held in devotion to the goddess. The beautifully built temple, its spiritual atmosphere, and centuries-old traditions make it a must-visit destination for those seeking blessings and cultural experiences. Since the temple is located a good distance from Bhuj, most devotees prefer booking a comfortable taxi, cab, or tempo traveller service from Bhuj for a convenient pilgrimage. Whether travelling with family or in a large group, hiring a reliable car rental or bus service for Mata No Madh ensures a smooth and hassle-free journey.', 'mata-no-madh-hariom.jpg', 3, 1),
  (8, 'NARAYAN SAROVAR', 'narayan-sarovar', 'Temple', '130 km', 'October to March — pleasant winter weather ideal for a peaceful pilgrimage and comfortable temple visits.', 'Narayan Sarovar is a sacred pilgrimage destination in Kutch, Gujarat, known for its ancient temples, peaceful surroundings, and spiritual significance. It is one of the five holy lakes of Hinduism and an important religious attraction in the region.', 'Narayan Sarovar is one of the most sacred pilgrimage sites in India, located in the Lakhpat taluka of the Kutch district in Gujarat. Considered one of the five holy lakes (Panch Sarovar) mentioned in Hindu scriptures, this revered destination holds immense spiritual significance for devotees across the country. The serene lake is surrounded by a cluster of beautiful ancient temples dedicated to Lord Vishnu, including the famous Shri Trikamrai Temple, built with exquisite architecture and deep devotion. The peaceful and divine atmosphere of Narayan Sarovar attracts pilgrims and travellers seeking blessings, tranquillity, and a spiritual retreat. Since the site is located in a remote region near the coast, most visitors prefer booking a comfortable taxi, cab, or tempo traveller service from Bhuj for a convenient pilgrimage. Whether travelling with family or in a group, hiring a reliable car rental or bus service for Narayan Sarovar ensures a smooth and peaceful journey.', 'narayan-sarovar-hariom.jpg', 4, 1),
  (9, 'RANN UTSAV', 'rann-utsav', 'FESTIVAL', '80', 'November to February during the festival season, with full-moon nights offering the most magical white desert views.', 'Rann Utsav is a vibrant cultural festival in the Great Rann of Kutch, Gujarat, showcasing the region’s traditional music, dance, handicrafts, cuisine, and breathtaking white desert landscapes. It offers visitors a unique experience of Kutch’s rich culture and natural beauty.', 'Rann Utsav is a vibrant cultural festival held every year in the vast white salt desert of the Great Rann of Kutch, Gujarat. Spanning several months from winter to early spring, this world-famous festival transforms the endless white landscape into a lively hub of Kutchi culture, art, music, and hospitality. Visitors stay in a beautifully designed luxury tent city that offers a perfect blend of traditional charm and modern comfort. To reach this remote desert wonder comfortably, most travellers prefer booking a reliable taxi, cab, or tempo traveller service from Bhuj, ensuring a smooth and hassle-free journey. From folk performances and handicraft bazaars to breathtaking full-moon nights over the shimmering white desert, Rann Utsav is a once-in-a-lifetime experience. Whether you are travelling solo, as a family, or in a large group, hiring a car rental or bus service for the Rann of Kutch makes your trip convenient and memorable.', 'rann-utsav-hariom.jpg', 5, 1),
  (10, 'KOTESWAR MAHADEV TEMPLE', 'koteswar-mahadev-temple', 'TEMPLE', '162', 'Otober to March — pleasant winter weather ideal for temple visits and enjoying the beautiful coastal views.', 'Koteswar Mahadev is a revered Shiva temple located near the Arabian Sea in Kutch, Gujarat. Known for its peaceful coastal setting and spiritual significance, it is a popular pilgrimage destination and an important attraction near Narayan Sarovar.', 'Koteshwar Mahadev Temple is an ancient and highly revered Shiva temple located at the westernmost tip of India, near Narayan Sarovar in the Lakhpat taluka of Kutch, Gujarat. Standing majestically on the shores of the Arabian Sea, this sacred temple marks the point where the land of India ends, making it a spiritually and geographically significant destination. Dedicated to Lord Shiva, the temple is steeped in legend and mythology, drawing devotees who come to seek blessings and witness the divine coastal setting. The mesmerising views of the sea, the peaceful surroundings, and the spiritual aura make Koteshwar a truly unique pilgrimage spot. Since the temple is located in a remote coastal area, most travellers prefer booking a comfortable taxi, cab, or tempo traveller service from Bhuj for a convenient visit. Whether travelling with family or in a group, hiring a reliable car rental or bus service for Koteshwar Temple ensures a smooth and peaceful journey.', 'koteshwar-mahadev-temple-hariom.jpg', 6, 1),
  (11, 'FOSSIL PARK- DHOLAVIRA', 'fossil-park-dholavira', 'Geological Site', '140', 'October to March — cool and pleasant winter weather ideal for exploring the park and the surrounding desert landscape.', 'Fossil Park Dholavira is a fascinating attraction near Dholavira, Kutch, showcasing ancient fossils and geological remains that offer a glimpse into the region’s prehistoric past. It is an interesting stop for visitors exploring the natural and historical heritage of Kutch.', 'Fossil Park in Kutch is a fascinating natural attraction that takes visitors on a journey millions of years back in time. Located near Dholavira on the way to the white desert, this unique park preserves ancient fossilised wood, marine fossils, and rock formations that offer a rare glimpse into the prehistoric era of the region. It is a paradise for nature lovers, students, and curious travellers who wish to explore the geological history of Kutch. The park highlights how this desert land was once covered by the sea, making it an educational and awe-inspiring destination. Since Fossil Park lies in a remote area near Khadir Bet, most travellers prefer booking a comfortable taxi, cab, or tempo traveller service from Bhuj to reach here easily. Whether travelling with family or in a group, hiring a reliable car rental or bus service for Fossil Park ensures a smooth and enjoyable journey.', 'fossil-park-dholavira-hariom.jpg', 7, 1),
  (12, 'ROAD TO HEAVEN', 'road-to-heaven', 'VIEWPOINT', '100', 'October to March — cool winter weather with the white desert at its most stunning, perfect for a scenic and memorable dr', 'Road to Heaven is a scenic attraction near Dholavira, Kutch, famous for its breathtaking landscape, open salt plains, and beautiful views. It offers a peaceful and memorable experience for travellers exploring the unique beauty of the Rann of Kutch.', 'The Road to Heaven is one of the most breathtaking and Instagram-famous stretches in Kutch, connecting Khadir Bet to the mainland through the vast white desert. This mesmerising road appears to float on an endless sheet of white salt, with shimmering water on both sides during certain seasons, creating a surreal, dreamlike experience. Officially known as the Khadir Bet road, it has become a must-visit attraction for travellers heading towards Dholavira, offering some of the most spectacular views in the region. Driving through this heavenly stretch, surrounded by the glistening white Rann, feels like a journey through another world. Since the Road to Heaven lies in a remote desert area, most travellers prefer booking a comfortable taxi, cab, or tempo traveller service from Bhuj to enjoy the drive safely and comfortably. Whether travelling with family or in a group, hiring a reliable car rental or bus service for the Road to Heaven ensures a smooth and unforgettable journey.', 'road-to-heaven-hariom.jpg', 8, 1),
  (13, 'SUNSET POINT DHOLAVIRA', 'sunset-point-dholavira', 'NATURE', '140', 'October to March — pleasant winter evenings offering the clearest and most spectacular sunset views over the white deser', 'Sunset Point Dholavira is a beautiful spot to witness breathtaking sunsets over the vast landscapes of Kutch. Enjoy panoramic views, peaceful surroundings, and stunning golden-hour moments, making it a perfect place for photography and nature lovers visiting Dholavira.', 'Sunset Point in Dholavira is a stunning viewpoint that offers one of the most spectacular sunset experiences in the entire Kutch region. Located near the ancient Dholavira site on Khadir Bet, this scenic spot lets visitors witness the golden sun sinking slowly over the vast white desert, painting the sky in mesmerising shades of orange, pink, and purple. The panoramic views of the endless white Rann glowing under the setting sun create a peaceful and unforgettable atmosphere, making it a favourite spot for photographers and nature lovers. It is the perfect place to end a day of exploring the historic ruins and desert landscapes of Dholavira. Since Sunset Point is located in a remote area near Khadir Bet, travellers usually prefer booking a comfortable taxi, cab, or tempo traveller service from Bhuj for a relaxed trip. Whether visiting with family or in a group, hiring a reliable car rental or bus service for Dholavira Sunset Point makes the journey smooth and enjoyable.', 'sunset-point-dholavira-hariom-tours-and-travels.webp', 9, 1),
  (14, 'ARCHAEOLOGICAL MUSEUM, DHOLAVIRA', 'archaeological-museum-dholavira', 'MUSEUM', '140', 'October to March — pleasant winter weather ideal for exploring the museum and the nearby Dholavira archaeological site.', 'The Archaeological Museum in Dholavira showcases fascinating artefacts, pottery, tools, ornaments, and other discoveries from the ancient Harappan Civilization. It offers visitors a deeper insight into the rich history, culture, and archaeological significance of Dholavira.', 'The Archaeological Museum at Dholavira is a fascinating destination that beautifully preserves and displays the rich heritage of the ancient Indus Valley Civilisation. Located right next to the famous Dholavira excavation site on Khadir Bet, this museum houses a remarkable collection of artefacts, seals, pottery, ornaments, tools, and other relics unearthed from the Harappan city. Each exhibit offers a captivating glimpse into the advanced lifestyle, craftsmanship, and urban planning of a civilisation that thrived over 4,500 years ago. Well-organised galleries and informative displays make it an enriching experience for history lovers, students, and curious travellers alike. As the museum is located in the remote Khadir Bet region, most visitors prefer booking a comfortable taxi, cab, or tempo traveller service from Bhuj to reach here conveniently. Whether travelling with family or in a group, hiring a reliable car rental or bus service for Dholavira makes exploring this historic treasure smooth and memorable.', 'archaeology-museum-hariom.webp', 10, 1),
  (15, '72 JINALAY TEMPLE MANDVI', '72-jinalay-temple-mandvi', 'JAIN TIRTH', '50', 'October to March — pleasant winter weather ideal for temple visits and combining your trip with nearby Mandvi attraction', '72 Jinalay Temple in Mandvi, Kutch, is a beautiful Jain temple complex known for its peaceful spiritual atmosphere, intricate architecture, and religious significance. A serene destination for visitors seeking culture, heritage, and devotion.', '72 Jinalay is a magnificent Jain temple complex located at Koday village near Mandvi in the Kutch district of Gujarat. Renowned for its breathtaking architecture and spiritual serenity, this grand temple features 72 beautifully carved shrines (Jinalayas) dedicated to the Jain Tirthankaras, surrounding a majestic central temple. The intricate marble work, stunning craftsmanship, and peaceful ambience make it one of the most important Jain pilgrimage centres in the region. The temple''s elegant design, towering spires, and detailed carvings reflect the rich devotion and artistry of Jain culture, attracting pilgrims and tourists alike. Its calm and divine atmosphere offers visitors a truly soulful experience. Since the temple is located a short distance from Mandvi, most travellers prefer booking a comfortable taxi, cab, or tempo traveller service from Bhuj for a convenient visit. Whether travelling with family or in a large group, hiring a reliable car rental or bus service for 72 Jinalay ensures a smooth and peaceful pilgrimage.', '72-jinalaya-mandvi-hariom.webp', 11, 1),
  (16, 'VIJAY VILLAS PALACE MANDVI', 'vijay-villas-palace-amndvi', 'PALACE', '70', 'October to March — pleasant winter weather ideal for exploring the palace, gardens, and the nearby Mandvi Beach.', 'Vijay villas palace is a magnificent historic palace near Mandvi, known for its stunning Indo-Saracenic architecture, royal heritage, lush gardens, and beautiful views of the Arabian Sea. It is a popular attraction for experiencing the grandeur and legacy of Kutch’s royal past.', 'Vijay Vilas Palace is a stunning royal heritage monument located near Mandvi in the Kutch district of Gujarat. Built in the 1920s by the Maharao of Kutch as a summer retreat for the royal family, this magnificent palace is a beautiful example of Rajput architecture blended with intricate craftsmanship. Set amidst lush green gardens and located close to a private beach, the palace features grand domes, carved balconies, elegant jharokhas, and a central high dome that offers panoramic views of the surrounding landscape and the Arabian Sea. Vijay Vilas Palace has also gained fame as a popular filming location for several Bollywood movies, adding to its charm. Its royal ambience, historic beauty, and serene surroundings make it a must-visit attraction. Since the palace is located near Mandvi, most travellers prefer booking a comfortable taxi, cab, or tempo traveller service from Bhuj for a convenient visit. Whether travelling with family or in a group, hiring a reliable car rental or bus service for Vijay Vilas Palace ensures a smooth and enjoyable journey.', 'vijay-vilas-palace-hariom.png', 12, 1),
  (17, 'SHYAMJI KRISHNA VERMA KRANTI TEERTH MANDVI', 'shyamji-krishna-verma-kranti-teerth-mandvi', 'MEMORIAL', '65', 'October to March — pleasant winter weather ideal for exploring the memorial and combining it with a visit to nearby Mand', 'Shyamji Krishna Varma Memorial, Mandvi, is a historic site dedicated to the renowned freedom fighter and revolutionary Shyamji Krishna Varma. It showcases his life, contributions, and legacy, making it an important cultural and historical attraction in Mandvi, Kutch.', 'Shyamji Krishna Verma Kranti Teerth is a proud national memorial located near Mandvi in the Kutch district of Gujarat, dedicated to the great revolutionary and freedom fighter Shyamji Krishna Verma. Built to honour his invaluable contribution to India''s freedom struggle, this beautifully designed memorial complex features a replica of India House in London, where he inspired many Indian revolutionaries. The site showcases his life, ideology, and sacrifices through exhibits, statues, and well-maintained gardens, making it a place of patriotic pride and historical importance. Its striking architecture and serene surroundings attract history enthusiasts and travellers from across the country. Since the memorial is located a short distance from Mandvi town, visitors often book a comfortable taxi, cab, or tempo traveller service from Bhuj for a convenient trip. Whether travelling with family or in a group, hiring a reliable car rental or bus service for Kranti Teerth Mandvi makes the journey smooth and hassle-free.', 'shyamji-krishna-varma-memorial-hariom.webp', 13, 1),
  (18, 'KALA DUNGAR (BLACK HILL)', 'kala-dungar-black-hill', 'HIGHEST POINT OF KUTCH', '90', 'October to March — cool winter weather with clear skies, perfect for panoramic desert views and a spectacular sunset.', 'Kala Dungar, also known as Black Hill, is the highest point in Kutch, Gujarat. Famous for its breathtaking panoramic views of the Great Rann of Kutch, it is a popular tourist attraction offering stunning landscapes, sunsets, and a unique experience of the Rann’s vast white salt desert.', 'Kala Dungar, also known as Black Hill, is the highest point in the Kutch district of Gujarat and one of the most popular tourist attractions in the region. Standing at around 462 metres, it offers a breathtaking panoramic view of the vast white Rann of Kutch stretching endlessly to the horizon — a sight that looks especially magical during sunset and on full-moon nights. The hilltop is also home to the ancient Dattatreya Temple, which carries centuries-old legends and traditions. Kala Dungar is famously known for its mysterious "magnetic hill" phenomenon, where vehicles appear to move uphill on their own, adding an element of wonder to the visit. Since the hill is located in a remote area near the India-Pakistan border, travellers usually prefer booking a comfortable taxi, cab, or tempo traveller service from Bhuj for a convenient trip. Whether visiting with family or in a group, hiring a reliable car rental or bus service for Kala Dungar ensures a smooth and enjoyable journey.', 'kalo-dungar-hariom.jpg', 14, 1),
  (19, 'AINA MAHAL, BHUJ', 'aina-mahal-bhuj', 'PALACE', 'CITY TOUR', 'Explore the stunning hall of mirrors and ornate glasswork Admire the Venetian-style chandeliers and royal interiors Marv', 'Aina Mahal is a magnificent 18th-century palace in Bhuj, Kutch, renowned for its intricate architecture, beautiful mirror work, ornate carvings, and historic royal heritage. A must-visit attraction for experiencing the rich culture and craftsmanship of Kutch', 'Aina Mahal, also known as the "Palace of Mirrors", is a stunning 18th-century royal palace located in the heart of Bhuj in the Kutch district of Gujarat. Built during the reign of Maharao Lakhpatji, this architectural masterpiece beautifully blends traditional Kutchi craftsmanship with European design influences, brought to life by the legendary local artisan Ram Singh Malam. The palace is famous for its exquisite hall of mirrors, ornate glasswork, marble floors surrounded by fountains, Venetian-style chandeliers, and intricately decorated interiors that reflect the grandeur of the erstwhile royal era. Today, Aina Mahal serves as a museum, showcasing rare artefacts, royal memorabilia, paintings, and antique collections that offer a fascinating glimpse into the rich history and culture of Kutch. Its timeless elegance makes it one of the most iconic heritage attractions in Bhuj. Since Aina Mahal is centrally located in Bhuj, travellers can easily book a comfortable taxi, cab, or tempo traveller service from Bhuj for local sightseeing. Whether travelling with family or in a group, hiring a reliable car rental or bus service in Bhuj ensures a smooth and convenient city tour.', 'aina-mahel-bhuj-hariom.webp', 15, 1),
  (20, 'MANDVI BEACH', 'mandvi-beach', 'BEACH', '80', 'October to March — pleasant winter weather ideal for relaxing on the beach, enjoying water sports, and watching the suns', 'Mandvi Beach is a beautiful coastal destination in Kutch, Gujarat, known for its golden sands, peaceful Arabian Sea views, refreshing sea breeze, and stunning sunsets. It is an ideal spot for relaxation, family outings, and enjoying the charm of Mandvi’s coastline.', 'Mandvi Beach is one of the most beautiful and popular beach destinations in the Kutch district of Gujarat, located along the pristine coastline of the Arabian Sea near the historic town of Mandvi. Known for its clean golden sands, gentle waves, and refreshing sea breeze, this scenic beach offers the perfect getaway for families, couples, and travellers looking to relax and unwind. The beach is famous for its wide range of activities, from thrilling camel and horse rides to exciting water sports, making it a lively yet peaceful spot. The stunning sunset views over the sea, along with the nearby Vijay Vilas Palace and traditional ship-building yard, add to Mandvi''s charm as a complete coastal experience. Its serene atmosphere and vibrant surroundings make it a must-visit attraction in Kutch. Since Mandvi is located a short distance from Bhuj, most travellers prefer booking a comfortable taxi, cab, or tempo traveller service from Bhuj for a convenient beach trip. Whether travelling with family or in a group, hiring a reliable car rental or bus service for Mandvi Beach ensures a smooth and enjoyable journey.', 'mandvi-beach-hari-om-tours-and-travels.jpg', 16, 1),
  (21, 'ROGAN ART (NIRONA VILLAGE), KUTCH', 'rogan-art-nirona-village-kutch', 'HANDICRAFT (VILLAGE)', '45', 'October to March — pleasant winter weather ideal for the drive to Nirona, especially during the Rann Utsav season when c', 'Discover the traditional Rogan Art of Nirona, a unique textile painting craft from Kutch, Gujarat. Made using vibrant natural colours and castor oil-based paint, this intricate art is handcrafted on fabric and showcases the rich cultural heritage and artistic traditions of Kutch.', 'Rogan Art is a rare and exquisite 400-year-old craft practised in Nirona village of the Kutch district in Gujarat, and today it survives thanks to the dedication of the Khatri family, the last remaining practitioners of this ancient art form in the world. In this remarkable technique, castor oil is boiled and mixed with natural colours to create a thick, elastic paint, which artisans skilfully draw into intricate patterns on fabric using a metal stylus — without the brush ever touching the cloth. The stunning motifs of flowers, peacocks, and the famous Tree of Life are created freehand, entirely from memory, making each piece a one-of-a-kind masterpiece. Rogan Art gained international recognition when the Prime Minister of India gifted a Rogan painting to the President of the United States. A visit to Nirona lets travellers witness this dying art form live, interact with the master artisans, and take home a truly unique piece of Kutchi heritage. Since Nirona is located a good distance from Bhuj, most travellers prefer booking a comfortable taxi, cab, or tempo traveller service from Bhuj for a convenient visit. Whether travelling with family or in a group, hiring a reliable car rental or bus service for Nirona ensures a smooth and enjoyable journey.', 'rogan-art-hariom.jpg', 17, 1),
  (22, 'KUTCH MUSEUM, BHUJ', 'kutch-museum-bhuj', 'MUSEUM', 'CITY TOUR', 'October to March — pleasant winter weather ideal for exploring the museum and combining it with other Bhuj city attracti', 'Kutch Museum in Bhuj is Gujarat’s oldest museum, showcasing the rich history, culture, tribal heritage, traditional textiles, handicrafts, coins, and archaeological treasures of Kutch. It is an excellent place to explore the region’s vibrant cultural heritage.', 'Kutch Museum, located in the heart of Bhuj in Gujarat, is the oldest museum in the state, established in 1877 by Maharao Khengarji III. Originally known as the Fergusson Museum, this historic institution stands beside the scenic Hamirsar Lake and is a treasure trove of the rich cultural, artistic, and historical heritage of the Kutch region. The museum houses an impressive collection of ancient artefacts, including tribal art, traditional Kutchi embroidery, textiles, weapons, musical instruments, coins, paintings, and rare relics that showcase the diverse traditions of the region. One of its major highlights is the collection of Kshatrapa inscriptions and exhibits depicting the lifestyle and crafts of local tribal communities. A visit to Kutch Museum offers a fascinating journey through the history and folk culture of Kutch, making it a must-visit for history and art lovers. Since the museum is centrally located in Bhuj, travellers can easily book a comfortable taxi, cab, or tempo traveller service from Bhuj for local sightseeing. Whether travelling with family or in a group, hiring a reliable car rental or bus service in Bhuj ensures a smooth and convenient city tour.', 'kutch-museum-hariom.jpg', 18, 1),
  (23, 'SHREE SWAMINARAYAN TEMPLE, BHUJ', 'shree-swaminarayan-temple-bhuj', 'TEMPLE', 'CITY TOUR', 'October to March — pleasant winter weather ideal for temple darshan and exploring other Bhuj city attractions.', 'Shree Swaminarayan Temple is a beautiful and spiritually significant Hindu temple in Bhuj, known for its peaceful atmosphere, intricate architecture, and vibrant religious traditions. It is an important pilgrimage and cultural attraction for visitors exploring Bhuj and Kutch.', 'Shree Swaminarayan Temple in Bhuj is one of the most magnificent and spiritually significant temples in the Kutch district of Gujarat. The original temple, built in 1822 during the time of Lord Swaminarayan himself, was one of the first six temples established by the sect. After it was damaged in the devastating 2001 earthquake, a stunning new temple was constructed nearby, showcasing breathtaking architecture crafted from Italian marble and gold work. The temple''s intricately carved pillars, ornate domes, and beautifully adorned deities create a divine and awe-inspiring atmosphere that attracts thousands of devotees and tourists from across the country. The peaceful surroundings, colourful artwork, and grand design make it a spiritual and architectural marvel. A visit here offers both religious blessings and a feast for the eyes. Since the temple is centrally located in Bhuj, travellers can easily book a comfortable taxi, cab, or tempo traveller service from Bhuj for local darshan and sightseeing. Whether travelling with family or in a group, hiring a reliable car rental or bus service in Bhuj ensures a smooth and convenient visit.', 'shree-swaminarayan-temple-bhuj-hariom-1787642349.webp', 19, 1),
  (24, 'HIRALAXMI MEMORIAL CRAFT PARK (BHUJODI), BHUJ', 'hiralaxmi-memorial-craft-park-bhujodi-bhuj', 'CULTURAL', '10', 'October to March — pleasant winter weather ideal for comfortable shopping and exploring the craft park, especially durin', 'Hiralaxmi Memorial Craft Park (Bhujodi), Bhuj — known for traditional Kutch handicrafts, handloom weaving, embroidery, and local artisan culture.', 'Hiralaxmi Memorial Craft Park, located in Bhujodi village near Bhuj in the Kutch district of Gujarat, is a vibrant hub celebrating the rich handicraft heritage of the region. Spread across a beautifully landscaped area, this craft park serves as a permanent marketplace where local artisans directly showcase and sell their exquisite handmade creations. Visitors can explore a stunning variety of authentic Kutchi crafts, including intricate embroidery, bandhani textiles, handwoven shawls, leatherwork, pottery, wood carvings, and traditional handicrafts. The park not only supports and empowers local craftsmen by giving them a direct platform but also offers travellers a chance to buy genuine souvenirs while interacting with the artisans themselves. With its cultural charm, live craft demonstrations, and shopping opportunities, Hiralaxmi Craft Park is a must-visit destination for art and handicraft lovers. Since Bhujodi is located a short distance from Bhuj, most travellers prefer booking a comfortable taxi, cab, or tempo traveller service from Bhuj for a convenient shopping trip. Whether travelling with family or in a group, hiring a reliable car rental or bus service for Bhujodi ensures a smooth and enjoyable journey.', 'hiralaxmi-memorial-craft-park-bhujodi-bhuj-hariom.webp', 20, 1),
  (25, 'SMRITIVAN EARTHQUAKE MEMORIAL ( MUSEUM ) , BHUJ', 'smritivan-earthquake-memorial-museum-bhuj', 'MUSEUM', 'CITY TOUR', 'October to March — pleasant winter weather ideal for exploring the expansive memorial; evening visits offer beautiful vi', 'Smritivan Earthquake Memorial & Museum, Bhuj, is a unique memorial dedicated to the victims of the devastating 2001 Gujarat earthquake. Set amidst beautifully landscaped surroundings, the museum offers an immersive experience showcasing the region’s history, resilience, culture, and journey of rebuilding.', 'Smritivan Earthquake Memorial and Museum is a world-class memorial located on the Bhujiyo Dungar (Bhujia Hill) in Bhuj, dedicated to the memory of the thousands of lives lost in the devastating 2001 Gujarat earthquake. Spread across a vast area, this beautifully designed memorial is one of the largest of its kind in the world and stands as a symbol of resilience, remembrance, and rebirth. The site features a state-of-the-art museum with seven immersive blocks that showcase the history, culture, and geology of Kutch, along with a powerful 5D simulator that recreates the experience of the earthquake. The memorial also includes reservoirs, thousands of planted trees, and memorial walls inscribed with the names of the victims, creating a serene and emotional space for reflection. Inaugurated in 2022, Smritivan has quickly become one of the most visited and inspiring attractions in Bhuj. Since the memorial is located close to Bhuj city, travellers can easily book a comfortable taxi, cab, or tempo traveller service from Bhuj for a convenient visit. Whether travelling with family or in a group, hiring a reliable car rental or bus service in Bhuj ensures a smooth and enjoyable journey.', 'smritivan-earthquake-memorial-museum-bhuj-hariom.jpg', 22, 1),
  (26, 'BHUJODI  VILLAGE , BHUJ', 'bhujodi-village-bhuj', 'HANDICRAFT / VILLAGE', '10', 'October to March — pleasant winter weather ideal for exploring the village, especially during the Rann Utsav season when', 'Bhujodi is a renowned traditional handicraft village near Bhuj, known for its vibrant Kutchi textiles, handwoven shawls, blankets, embroidery, and traditional crafts. It offers visitors an authentic glimpse into the rich culture and craftsmanship of Kutch', 'Bhujodi is a famous handicraft and weaving village located just a short distance from Bhuj in the Kutch district of Gujarat. Renowned as one of the most important textile hubs in the region, this vibrant village is home to hundreds of skilled artisans and weavers who have preserved their traditional crafts for generations. Bhujodi is especially celebrated for its exquisite handwoven shawls, stoles, blankets, and fabrics, along with intricate Kutchi embroidery, tie-and-dye bandhani, and block printing. Visitors can walk through the village, watch artisans at work on their looms, and purchase authentic handmade textiles directly from the craftsmen at fair prices. The warm hospitality, rich cultural experience, and chance to witness age-old weaving traditions make Bhujodi a must-visit destination for handicraft and textile lovers. Since Bhujodi is located close to Bhuj, most travellers prefer booking a comfortable taxi, cab, or tempo traveller service from Bhuj for a convenient trip. Whether travelling with family or in a group, hiring a reliable car rental or bus service for Bhujodi ensures a smooth and enjoyable journey.', 'bhujodi-village-harioim.png', 23, 1);

