  (1, 'White Rann day trip', 'white-rann-day-trip', 'day', '1 day', 'approx 160 km', 3500.00, 'Bhuj to Dhordo for the salt desert, with a stop at Kalo Dungar for the view across the Rann.', 'White Rann at Dhordo\nKalo Dungar viewpoint\nBhirandiyara for local sweets', NULL, 1, 1, 1),
  (2, 'Mandvi beach day trip', 'mandvi-beach-day-trip', 'day', '1 day', 'approx 130 km', 2800.00, 'Coastal run to Mandvi with the shipbuilding yard, the beach and Vijay Vilas Palace.', 'Mandvi beach and windmills\nVijay Vilas Palace\nTraditional shipbuilding yard', NULL, 1, 2, 1),
